SELECT -- route, SD_ID, seat_count, COUNT(DISTINCT tin) txn_count, COUNT(DISTINCT group_txns) group_txn_count FROM ( SELECT t.tin, CAST(DATE_TRUNC('day', at_timezone(t.date_of_issue, 'Asia/Kolkata')) AS DATE) AS doi, (t.source_location ||'-'|| t.destination_location) AS route, CAST(t.source_location_id AS VARCHAR) ||'-'|| CAST(t.destination_location_id AS VARCHAR) AS SD_ID, CASE WHEN p.payment_system_ref_no LIKE '%ALLG%' OR p.payment_system_ref_no LIKE 'MULG%' THEN t.tin END AS group_txns, MAX(seat_count) AS seat_count FROM "transaction"."bus_ticket_events" t JOIN "transaction"."bus_payment_events" p ON t.order_uuid = p.order_uuid WHERE t.date_of_issue >= TIMESTAMP '2026-04-15 00:00:00' AND t.date_of_issue < TIMESTAMP '2026-04-20 00:00:00' AND p.time_of_event >= TIMESTAMP '2026-04-15 00:00:00' AND p.time_of_event < TIMESTAMP '2026-04-20 00:00:00' and t.country_code = 'IND' AND p.country_code = 'IND' -- AND (t.source_location_id, t.destination_location_id) IN ((602, 123),(123, 602),(736, 733),(733, 736),(123, 126),(759, 733),(733, 759),(733, 737),(126, 123),(123, 611),(737, 733),(611, 123),(122, 236),(833, 733),(123, 236),(733, 833),(236, 123),(122, 123),(122, 123),(123, 122),(123, 141),(123, 122),(141, 123),(122, 126),(126, 122),(235, 123),(833, 734),(123, 504),(123, 235),(733, 1439),(504, 123),(123, 458),(233, 141),(78027, 733),(833, 759),(733, 735),(733, 734),(735, 733),(123, 602),(759, 833),(1523, 733),(733, 78027),(733, 1523),(734, 833),(577, 123),(141, 233),(1439, 733),(69359, 123),(736, 759),(66006, 123)) AND t.event_class = 2 AND t.event_type = 101 -- and p.payment_system = 'OP_SL_OFFER' GROUP BY 1, 2, 3, 4, 5 ) a GROUP BY 1 -- , 2, 3 ORDER BY 1
